import React, { useMemo } from "react";
import { random, useCurrentFrame } from "remotion";
import { palette } from "../theme/palette";

/**
 * Falling petals in scene space (1080×1920 SVG). Each petal drifts on its own slow sine,
 * tumbles, and loops — seeded, so every render is identical.
 */
export const FallingPetals: React.FC<{
  count?: number;
  seed?: string;
  colors?: string[];
  speed?: number;
  start?: number;
  size?: number;
  width?: number;
  height?: number;
  opacity?: number;
}> = ({
  count = 26,
  seed = "petals",
  colors = [palette.rose, palette.marigold, palette.roseLight, palette.turmeric],
  speed = 1,
  start = 0,
  size = 1,
  width = 1080,
  height = 1920,
  opacity = 1,
}) => {
  const frame = useCurrentFrame() - start;
  const petals = useMemo(
    () =>
      new Array(count).fill(0).map((_, i) => ({
        x: random(`${seed}-x${i}`) * width,
        delay: random(`${seed}-d${i}`) * 200,
        v: (2.2 + random(`${seed}-v${i}`) * 2.2) * speed,
        sway: 20 + random(`${seed}-s${i}`) * 40,
        period: 60 + random(`${seed}-p${i}`) * 80,
        spin: (random(`${seed}-r${i}`) - 0.5) * 8,
        s: (0.7 + random(`${seed}-z${i}`) * 0.8) * size,
        color: colors[i % colors.length],
      })),
    [count, seed, speed, size, width, colors],
  );
  if (frame < 0) return null;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ position: "absolute", inset: 0, overflow: "visible", pointerEvents: "none", opacity }}>
      {petals.map((p, i) => {
        const tt = frame + p.delay;
        const y = ((tt * p.v) % (height + 120)) - 60;
        const x = p.x + Math.sin((tt / p.period) * Math.PI * 2) * p.sway;
        const flip = Math.cos((tt / p.period) * Math.PI * 2);
        return (
          <g key={i} transform={`translate(${x} ${y}) rotate(${tt * p.spin}) scale(${p.s} ${p.s * (0.35 + Math.abs(flip) * 0.65)})`}>
            <path d="M0 0 C6 -8 16 -8 18 0 C16 7 6 8 0 0 Z" fill={p.color} />
          </g>
        );
      })}
    </svg>
  );
};

/** Twinkling gold dust / sparkle field. */
export const GoldDust: React.FC<{ count?: number; seed?: string; area?: [number, number, number, number]; start?: number; color?: string }> = ({
  count = 40,
  seed = "dust",
  area = [0, 0, 1080, 1920],
  start = 0,
  color = palette.goldPale,
}) => {
  const frame = useCurrentFrame() - start;
  const [ax, ay, aw, ah] = area;
  const pts = useMemo(
    () =>
      new Array(count).fill(0).map((_, i) => ({
        x: ax + random(`${seed}-x${i}`) * aw,
        y: ay + random(`${seed}-y${i}`) * ah,
        r: 1.2 + random(`${seed}-r${i}`) * 2.6,
        period: 40 + random(`${seed}-p${i}`) * 70,
        phase: random(`${seed}-ph${i}`) * Math.PI * 2,
        rise: 0.2 + random(`${seed}-u${i}`) * 0.5,
      })),
    [count, seed, ax, ay, aw, ah],
  );
  if (frame < 0) return null;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0, pointerEvents: "none", overflow: "visible" }}>
      {pts.map((p, i) => {
        const tw = 0.5 + 0.5 * Math.sin((frame / p.period) * Math.PI * 2 + p.phase);
        const y = p.y - frame * p.rise;
        return (
          <g key={i} opacity={tw * Math.min(1, frame / 15)}>
            <circle cx={p.x} cy={y} r={p.r * 2.6} fill={color} opacity={0.18} />
            <path d={`M${p.x} ${y - p.r * 2.4} L${p.x + p.r * 0.5} ${y} L${p.x} ${y + p.r * 2.4} L${p.x - p.r * 0.5} ${y} Z`} fill={color} />
            <path d={`M${p.x - p.r * 2.4} ${y} L${p.x} ${y + p.r * 0.5} L${p.x + p.r * 2.4} ${y} L${p.x} ${y - p.r * 0.5} Z`} fill={color} />
          </g>
        );
      })}
    </svg>
  );
};
